// Hàm lấy text theo ngôn ngữ
function getText(key) {
  const lang = getCurrentLanguage();
  return translations[lang][key] || translations['vi'][key] || key;
}

// Hàm lấy ngôn ngữ hiện tại
function getCurrentLanguage() {
  // Ưu tiên URL parameter
  const urlParams = new URLSearchParams(window.location.search);
  const urlLang = urlParams.get('lang');
  if (urlLang && (urlLang === 'vi' || urlLang === 'en')) {
    return urlLang;
  }
  
  // Nếu không có URL parameter, dùng localStorage
  const storedLang = localStorage.getItem('language');
  if (storedLang && (storedLang === 'vi' || storedLang === 'en')) {
    return storedLang;
  }
  
  // Mặc định là tiếng Việt
  return 'vi';
}

// Hàm đặt ngôn ngữ
function setLanguage(lang) {
  localStorage.setItem('language', lang);
  // Cập nhật URL parameter nếu có thể
  const url = new URL(window.location);
  url.searchParams.set('lang', lang);
  window.history.replaceState({}, '', url);
  
  // Cập nhật DOM trực tiếp thay vì reload
  updatePageLanguage();
}

// Hàm cập nhật tất cả text trong trang
function updatePageLanguage() {
  const lang = getCurrentLanguage();

  // Cập nhật document title
  const titleElement = document.querySelector('title[data-i18n]');
  if (titleElement) {
    const key = titleElement.getAttribute('data-i18n');
    document.title = getText(key);
  }

  // Cập nhật tất cả element có data-i18n attribute
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    element.textContent = getText(key);
  });

  // Cập nhật tất cả element có data-i18n-placeholder attribute
  document.querySelectorAll('[data-i18n-placeholder]').forEach(element => {
    const key = element.getAttribute('data-i18n-placeholder');
    element.placeholder = getText(key);
  });

  // Cập nhật tất cả element có data-i18n-title attribute
  document.querySelectorAll('[data-i18n-title]').forEach(element => {
    const key = element.getAttribute('data-i18n-title');
    element.title = getText(key);
  });
}

// Export functions
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { translations, getText, getCurrentLanguage, setLanguage, updatePageLanguage };
}
